('3ca00000-0000-4000-8000-000000000002','3c200000-0000-4000-8000-000000000001','3c900000-0000-4000-8000-000000000001','final-assessment',2,jsonb_build_object('en','Final'),jsonb_build_object('en','Final'),jsonb_build_object('module_role','final_assessment'),'3c100000-0000-4000-8000-000000000001');
