select ok((select questions from public.get_training_final_quiz_attempt('3c200000-0000-4000-8000-000000000001','3c300000-0000-4000-8000-000000000001','3c600000-0000-4000-8000-000000000001',current_setting('test.phase3c_enrollment')::uuid,current_setting('test.phase3c_attempt')::uuid))::text !~ 'answer|explanation|correct','learner question payload leaks no answers or explanations');
select lives_ok($$select * from public.start_training_final_quiz_attempt('3c200000-0000-4000-8000-000000000001','3c300000-0000-4000-8000-000000000001','3c600000-0000-4000-8000-000000000001',current_setting('test.phase3c_enrollment')::uuid,'en','3cc00000-0000-4000-8000-000000000001')$$,'duplicate start is idempotent');
select is((select count(*)::integer from public.training_quiz_attempts where enrollment_id=current_setting('test.phase3c_enrollment')::uuid),1,'duplicate start creates no attempt');
select throws_ok($$select * from public.start_training_final_quiz_attempt('3c200000-0000-4000-8000-000000000001','3c300000-0000-4000-8000-000000000001','3c600000-0000-4000-8000-000000000002',current_setting('test.phase3c_enrollment')::uuid,'en','3cc00000-0000-4000-8000-000000000002')$$,'P0002','Training enrollment is unavailable','cross-employee attempt is rejected');
select throws_ok($$select * from public.start_training_final_quiz_attempt('00000000-0000-4000-8000-000000000099','3c300000-0000-4000-8000-000000000001','3c600000-0000-4000-8000-000000000001',current_setting('test.phase3c_enrollment')::uuid,'en','3cc00000-0000-4000-8000-000000000002')$$,'42501','Training learner scope is invalid','cross-organization attempt is rejected');
select throws_ok($$select * from public.submit_training_final_quiz_attempt('3c200000-0000-4000-8000-000000000001','3c300000-0000-4000-8000-000000000001','3c600000-0000-4000-8000-000000000001',current_setting('test.phase3c_enrollment')::uuid,current_setting('test.phase3c_attempt')::uuid,'3cd00000-0000-4000-8000-000000000001',jsonb_build_array(jsonb_build_object('question_key','q-1','option_key','b')))$$,'22023','Exactly one answer per Final Quiz question is required','exactly 27 answers are required');
select throws_ok($$select * from public.submit_training_final_quiz_attempt('3c200000-0000-4000-8000-000000000001','3c300000-0000-4000-8000-000000000001','3c600000-0000-4000-8000-000000000001',current_setting('test.phase3c_enrollment')::uuid,current_setting('test.phase3c_attempt')::uuid,'3cd00000-0000-4000-8000-000000000001',(select jsonb_agg(jsonb_build_object('question_key',case when n=27 then 'unknown' else 'q-'||n end,'option_key','b')) from generate_series(1,27)n))$$,'22023','Final Quiz answer is invalid','unknown question is rejected');
select throws_ok($$select * from public.submit_training_final_quiz_attempt('3c200000-0000-4000-8000-000000000001','3c300000-0000-4000-8000-000000000001','3c600000-0000-4000-8000-000000000001',current_setting('test.phase3c_enrollment')::uuid,current_setting('test.phase3c_attempt')::uuid,'3cd00000-0000-4000-8000-000000000001',(select jsonb_agg(jsonb_build_object('question_key','q-'||n,'option_key',case when n=27 then 'invalid' else 'b' end)) from generate_series(1,27)n))$$,'22023','Final Quiz answer is invalid','unknown option is rejected');
select lives_ok($$select * from public.submit_training_final_quiz_attempt('3c200000-0000-4000-8000-000000000001','3c300000-0000-4000-8000-000000000001','3c600000-0000-4000-8000-000000000001',current_setting('test.phase3c_enrollment')::uuid,current_setting('test.phase3c_attempt')::uuid,'3cd00000-0000-4000-8000-000000000001',(select jsonb_agg(jsonb_build_object('question_key','q-'||n,'option_key',case when n<=21 then 'b' else 'a' end) order by n) from generate_series(1,27)n))$$,'21/27 submission succeeds');
select is((select passed from public.training_quiz_attempts where id=current_setting('test.phase3c_attempt')::uuid),false,'21/27 fails');
select is((select count(*)::integer from public.training_course_completions where enrollment_id=current_setting('test.phase3c_enrollment')::uuid),0,'failed attempt creates no completion');
select lives_ok($$select * from public.start_training_final_quiz_attempt('3c200000-0000-4000-8000-000000000001','3c300000-0000-4000-8000-000000000001','3c600000-0000-4000-8000-000000000001',current_setting('test.phase3c_enrollment')::uuid,'en','3cc00000-0000-4000-8000-000000000002')$$,'failure permits retake');
select set_config('test.phase3c_attempt2',(select id::text from public.training_quiz_attempts where enrollment_id=current_setting('test.phase3c_enrollment')::uuid and attempt_number=2),false);
select is((select attempt_number from public.training_quiz_attempts where id=current_setting('test.phase3c_attempt2')::uuid),2,'retake attempt number increments');
select lives_ok($$select * from public.submit_training_final_quiz_attempt('3c200000-0000-4000-8000-000000000001','3c300000-0000-4000-8000-000000000001','3c600000-0000-4000-8000-000000000001',current_setting('test.phase3c_enrollment')::uuid,current_setting('test.phase3c_attempt2')::uuid,'3cd00000-0000-4000-8000-000000000002',(select jsonb_agg(jsonb_build_object('question_key','q-'||n,'option_key',case when n<=22 then 'b' else 'a' end) order by n) from generate_series(1,27)n))$$,'22/27 submission succeeds');
select is((select passed from public.training_quiz_attempts where id=current_setting('test.phase3c_attempt2')::uuid),true,'22/27 passes');
select is((select count(*)::integer from public.training_course_completions where enrollment_id=current_setting('test.phase3c_enrollment')::uuid),1,'passing attempt creates one completion');
select set_config('test.phase3c_completed',(select completed_at::text from public.training_course_completions where enrollment_id=current_setting('test.phase3c_enrollment')::uuid),false);
select lives_ok($$select * from public.submit_training_final_quiz_attempt('3c200000-0000-4000-8000-000000000001','3c300000-0000-4000-8000-000000000001','3c600000-0000-4000-8000-000000000001',current_setting('test.phase3c_enrollment')::uuid,current_setting('test.phase3c_attempt2')::uuid,'3cd00000-0000-4000-8000-000000000002',(select jsonb_agg(jsonb_build_object('question_key','q-'||n,'option_key',case when n<=22 then 'b' else 'a' end) order by n) from generate_series(1,27)n))$$,'duplicate submit is idempotent');
select is((select completed_at::text from public.training_course_completions where enrollment_id=current_setting('test.phase3c_enrollment')::uuid),current_setting('test.phase3c_completed'),'completion timestamp remains immutable');
select throws_ok($$select * from public.submit_training_final_quiz_attempt('3c200000-0000-4000-8000-000000000001','3c300000-0000-4000-8000-000000000001','3c600000-0000-4000-8000-000000000001',current_setting('test.phase3c_enrollment')::uuid,current_setting('test.phase3c_attempt2')::uuid,'3cd00000-0000-4000-8000-000000000002',(select jsonb_agg(jsonb_build_object('question_key','q-'||n,'option_key','b') order by n) from generate_series(1,27)n))$$,'23505','Submitted Final Quiz attempts are immutable','changed replay payload is rejected');
select throws_ok(format('update public.training_quiz_attempts set score_bps=0 where id=%L',current_setting('test.phase3c_attempt2')),'55000','Submitted Training attempts are immutable','submitted attempt rows are immutable');
select is((select count(*)::integer from public.training_quiz_attempt_answers where attempt_id=current_setting('test.phase3c_attempt2')::uuid),27,'all selected answers are retained for audit');
select is((select identity_method from public.training_course_completions where enrollment_id=current_setting('test.phase3c_enrollment')::uuid),'branch_pin_employee_code','completion records lower-assurance identity method');
select is((select compliance_identity_verified from public.training_course_completions where enrollment_id=current_setting('test.phase3c_enrollment')::uuid),false,'completion is not mislabeled identity-verified compliance');
insert into public.branches(id,organization_id,name,code,timezone,active) values('3c300000-0000-4000-8000-000000000002','3c200000-0000-4000-8000-000000000001','Transferred Branch','P3CT','Asia/Riyadh',true);
update public.operational_staff set branch_id='3c300000-0000-4000-8000-000000000002' where id='3c600000-0000-4000-8000-000000000001';
select is((select count(*)::integer from public.training_course_completions where employee_id='3c600000-0000-4000-8000-000000000001'),1,'branch transfer cannot remove historical completion');
select * from finish();
rollback;
